FeatureScript 3112;
import(path : "onshape/std/geometry.fs", version : "3112.0");

// Fixture batch 084: hold lines and a cliff edge inside a side, fillets of circular edges on a cone and round a boss, a conic blend with a cylinder. Generated by tools/fixtures/gen-batch-084.mjs; do not edit.
// Each case builds its geometry at the origin and may return a map of values to check.

// Each face of a body: its area and its surface's type.
function faceProbe(context is Context, body is Query) returns array
{
    var out = [];
    for (var face in evaluateQuery(context, qOwnedByBody(body, EntityType.FACE)))
    {
        var entry = { "area" : roundToPrecision(evArea(context, { "entities" : face }) / millimeter ^ 2, 6) };
        try
        {
            entry["type"] = evSurfaceDefinition(context, { "face" : face, "returnBSplinesAsOther" : true }).surfaceType;
        }
        catch (error)
        {
            entry["type"] = "failed";
        }
        out = append(out, entry);
    }
    return out;
}

// face-blend: an upright of two faces (split 4 mm up) and a level wall, blended 5 mm, the split a tangent hold line
export function c001(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(1, 0, 0), vector(0, 1, 0)) });
    skLineSegment(s1, "l1", { "start" : vector(0, 0) * millimeter, "end" : vector(0, 4) * millimeter });
    skLineSegment(s1, "l2", { "start" : vector(0, 4) * millimeter, "end" : vector(0, 20) * millimeter });
    skSolve(s1);
    extrude(context, id + "floor", { "bodyType" : ExtendedToolBodyType.SURFACE, "surfaceEntities" : qOwnedByBody(qBodyType(qCreatedBy(id + "s1", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "endBound" : BoundingType.BLIND, "depth" : 30 * millimeter, "oppositeDirection" : false });
    const s2 = newSketchOnPlane(context, id + "s2", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skLineSegment(s2, "l1", { "start" : vector(0, 0) * millimeter, "end" : vector(30, 0) * millimeter });
    skSolve(s2);
    extrude(context, id + "wall", { "bodyType" : ExtendedToolBodyType.SURFACE, "surfaceEntities" : qOwnedByBody(qBodyType(qCreatedBy(id + "s2", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "endBound" : BoundingType.BLIND, "depth" : 20 * millimeter, "oppositeDirection" : true });
    faceBlend(context, id + "blend1", { "side1" : qOwnedByBody(qBodyType(qCreatedBy(id + "floor", EntityType.BODY), BodyType.SHEET), EntityType.FACE), "flipSide1" : false, "side2" : qOwnedByBody(qBodyType(qCreatedBy(id + "wall", EntityType.BODY), BodyType.SHEET), EntityType.FACE), "flipSide2" : false, "radius" : 5 * millimeter, "propagation" : false, "crossSection" : FaceBlendCrossSection.ROLLING_BALL, "blendControlType" : BlendControlType.RADIUS, "asymmetric" : false, "crossSectionShape" : FaceBlendCrossSectionShape.CIRCULAR, "tangentHoldLines" : true, "conicHoldLines" : false, "hasCliffEdges" : false, "hasCaps" : false, "hasLimits" : false, "hasHelpPoint" : false, "trim" : FaceBlendTrimType.WALLS, "detach" : false, "showSelection" : false, "showIsocurves" : false, "tangentEdges" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "floor", EntityType.BODY), BodyType.SHEET), EntityType.EDGE), vector(15, 0, 4) * millimeter), "inverseTangentEdges" : qNothing() });
    return { "floor" : faceProbe(context, qBodyType(qCreatedBy(id + "floor", EntityType.BODY), BodyType.SHEET)) };
}

