// fillet: a cone frustum (radius 10 at the bottom, 6 at the top, 20 tall): its top edge filleted with a conic section (rho 0.7), 2 mm
export function c005(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skLineSegment(s1, "l1", { "start" : vector(0, 0) * millimeter, "end" : vector(10, 0) * millimeter });
    skLineSegment(s1, "l2", { "start" : vector(10, 0) * millimeter, "end" : vector(6, 20) * millimeter });
    skLineSegment(s1, "l3", { "start" : vector(6, 20) * millimeter, "end" : vector(0, 20) * millimeter });
    skLineSegment(s1, "l4", { "start" : vector(0, 20) * millimeter, "end" : vector(0, 0) * millimeter });
    skSolve(s1);
    revolve(context, id + "base", { "entities" : qSketchRegion(id + "s1"), "axis" : qContainsPoint(qCreatedBy(id + "s1", EntityType.EDGE), vector(0, 0, 10) * millimeter), "fullRevolve" : true });
    fillet(context, id + "fillet1", { "entities" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(6, 0, 20) * millimeter), "radius" : 2 * millimeter, "crossSection" : FilletCrossSection.CONIC, "nonCircularRadius" : 2 * millimeter, "rho" : 0.7 });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID)) };
}

// fillet: a 40 × 40 × 10 block with a boss of radius 8, 10 tall, on its top: the edge round the boss's foot filleted with a curvature section (magnitude 0.5), 3 mm
export function c006(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(baseSketch, "rect1", { "firstCorner" : vector(-20, -20) * millimeter, "secondCorner" : vector(20, 20) * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter });
    const s2 = newSketchOnPlane(context, id + "s2", { "sketchPlane" : plane(vector(0, 0, 10) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(s2, "c1", { "center" : vector(0, 0) * millimeter, "radius" : 8 * millimeter });
    skSolve(s2);
    extrude(context, id + "boss", { "entities" : qSketchRegion(id + "s2"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter, "operationType" : NewBodyOperationType.ADD, "defaultScope" : false, "booleanScope" : qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID) });
    fillet(context, id + "fillet1", { "entities" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(8, 0, 10) * millimeter), "radius" : 3 * millimeter, "crossSection" : FilletCrossSection.CURVATURE, "nonCircularRadius" : 3 * millimeter, "magnitude" : 0.5 });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID)) };
}

